import React from "react";
import { fireEvent, render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import * as stories from "./Rating.stories";
import Rating from "./Rating";

const { Basic } = composeStories(stories) as any;

describe("Rating", () => {
  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("passes through props", () => {
    render(<Rating data-testid="rating" />);
    expect(screen.getByTestId("rating")).toBeTruthy();
  });

  it("calls callback with selected value", () => {
    const callback = jest.fn();
    render(<Rating onChange={callback} />);
    const items = screen.getAllByRole("radio");
    fireEvent.click(items[4]);
    expect(callback).toHaveBeenCalledTimes(1);
    expect(callback).toHaveBeenLastCalledWith(5);
  });

  it("clear selected value on click", () => {
    const callback = jest.fn();
    render(<Rating defaultValue={5} onChange={callback} />);
    const items = screen.getAllByRole("radio");
    fireEvent.click(items[4]);
    expect(callback).toHaveBeenCalledTimes(1);
    expect(callback).toHaveBeenLastCalledWith(0);
  });

  it("does not select value if readOnly", () => {
    const callback = jest.fn();
    render(<Rating readOnly onChange={callback} />);
    const items = screen.getAllByRole("radio");
    fireEvent.click(items[4]);
    expect(callback).toHaveBeenCalledTimes(0);
  });

  it("allow keyboard navigation", async () => {
    const callback = jest.fn();
    render(<Rating defaultValue={2} onChange={callback} />);
    const items = screen.getAllByRole("radio");
    await userEvent.tab();
    expect(items[1]).toHaveFocus();
    fireEvent.keyDown(items[1], { key: "ArrowRight" });
    fireEvent.keyDown(items[1], { key: "ArrowUp" });
    expect(callback).toHaveBeenCalledTimes(2);
    expect(callback).toHaveBeenLastCalledWith(4);
    fireEvent.keyDown(items[1], { key: "ArrowLeft" });
    fireEvent.keyDown(items[1], { key: "ArrowDown" });
    expect(callback).toHaveBeenCalledTimes(4);
    expect(callback).toHaveBeenLastCalledWith(2);
    fireEvent.keyDown(items[1], { key: "ArrowDown" });
    fireEvent.keyDown(items[1], { key: "ArrowDown" });
    fireEvent.keyDown(items[1], { key: "ArrowDown" });
    expect(callback).toHaveBeenCalledTimes(6);
    expect(callback).toHaveBeenLastCalledWith(0);
    fireEvent.keyDown(items[1], { key: "ArrowUp" });
    fireEvent.keyDown(items[1], { key: "ArrowUp" });
    fireEvent.keyDown(items[1], { key: "ArrowUp" });
    fireEvent.keyDown(items[1], { key: "ArrowUp" });
    fireEvent.keyDown(items[1], { key: "ArrowUp" });
    fireEvent.keyDown(items[1], { key: "ArrowUp" });
    expect(callback).toHaveBeenCalledTimes(11);
    expect(callback).toHaveBeenLastCalledWith(5);
  });
});
